import {xpBase} from './progression.js?v=12';
export const CHAPTERS=[
 ['O coração do farol','Ilyra','O farol voltou a brilhar, mas sua fonte foi fragmentada. Reconecte o primeiro selo para descobrir quem alterou a luz.','Selo de Lúmen','Fragmentos do farol'],
 ['Memórias sob as cinzas','Borun','As forjas foram apagadas de dentro para fora. Uma liga desconhecida está alimentando as criaturas do vale.','Forja Silenciosa','Amostras de liga viva'],
 ['A cidade enterrada','Selene','Uma caravana desapareceu seguindo reflexos nas dunas. O sinal de sua bússola ainda vem da cidade soterrada.','Bússola de Sárion','Lentes da caravana'],
 ['O inverno sem estrelas','Aeris','O observatório parou de enxergar o firmamento. Os cristais que o sustentam estão presos à fauna corrompida.','Observatório de Vesper','Cristais estelares'],
 ['A raiz do eclipse','Aeris','O bosque absorveu uma relíquia e agora repete o mesmo crepúsculo. Encontre a raiz que conserva essa memória.','Raiz Ancestral','Sementes de memória'],
 ['O juramento quebrado','Borun','As sentinelas ainda defendem uma cidadela que já caiu. Recupere as chaves para encerrar sua ordem de guerra.','Arquivo da Cidadela','Chaves de sentinela'],
 ['A voz abaixo do mundo','Ilyra','Um chamado atravessa o abismo e imita vozes conhecidas. O selo permite distinguir uma pessoa de seu eco.','Selo de Nhal','Fragmentos de eco'],
 ['A coroa sem soberano','Selene','Aster alimentou sua coroa com energia do mundo. Agora cada guardião conserva uma parte do mecanismo imperial.','Núcleo Imperial','Engrenagens astrais'],
 ['Reflexos que respiram','Aeris','O mar cristalizou instantes inteiros. Liberte as essências presas aos reflexos antes que a maré as apague.','Espelho da Maré','Essências de reflexo'],
 ['As órbitas partidas','Ilyra','A energia roubada mantém ilhas suspensas. Reative uma órbita para impedir que o firmamento caia sobre os reinos.','Âncora Celeste','Prismas de órbita'],
 ['A primeira assinatura','Borun','Na escadaria, todas as relíquias reconhecem o mesmo criador. Reúna suas inscrições para abrir o limiar final.','Limiar das Origens','Inscrições primordiais'],
 ['Quem herdará a origem','Ilyra','O Trono converte vontade em matéria. Desligue seus guardiões e decida proteger os selos que sustentam o mundo.','Coração da Origem','Fragmentos da vontade']
].map(([title,npc,story,landmark,collectible],region)=>({region,title,npc,story,landmark,collectible,target:8+Math.floor(region/3)*2,point:{x:27,y:9}}));
export function initChapters(p){if(!p.chapters)p.chapters=Object.fromEntries(Array.from({length:p.region||0},(_,i)=>[i,{stage:4,kills:CHAPTERS[i].target}]));return p.chapters;}
export function chapterState(p,region=p.region||0){return initChapters(p)[region]||{stage:0,kills:0};}
export function chapterProgress(p,event){if(p.quest<4||p.testMode&&event.type!=='visit')return false;const region=p.region||0;if(event.region!==undefined&&event.region!==region)return false;const definition=CHAPTERS[region];if(!definition)return false;const current=chapterState(p,region),state={...current};if(state.stage===0&&event.type==='visit'&&p.zone==='coast'&&Math.hypot(p.x-definition.point.x,p.y-definition.point.y)<2.2)state.stage=1;else if(state.stage===1&&event.type==='kill'&&!event.training){state.kills=Math.min(definition.target,(state.kills||0)+1);if(state.kills>=definition.target)state.stage=2;}else if(state.stage===2&&event.type==='dungeon')state.stage=3;else return false;p.chapters[region]=state;return state.stage!==current.stage;}
export function chapterReward(p,regions,region=p.region||0){const level=regions[region].range[0];return {gold:Math.round(500+level*level*1.5),xp:Math.ceil(xpBase(Math.max(level,Math.min(p.level,regions[region].range[1])))*1.5),plumes:5+region*2,essences:5+region*2};}
export function claimChapter(p,regions){const region=p.region||0,state=chapterState(p,region);if(p.testMode)return {ok:false,reason:'Laboratório não concede recompensas da campanha.'};if(state.stage!==3)return {ok:false,reason:'Conclua as etapas do capítulo.'};if(p.zone!=='coast'||Math.hypot(p.x-12,p.y-12)>3)return {ok:false,reason:'Retorne à Ilyra no ponto seguro para estabilizar o selo.'};const reward=chapterReward(p,regions);p.gold+=reward.gold;p.materials||={};p.materials['Pluma Astral']=(p.materials['Pluma Astral']||0)+reward.plumes;p.materials['Essência de Aura']=(p.materials['Essência de Aura']||0)+reward.essences;p.chapters[region]={...state,stage:4};return {ok:true,reward};}
export function chapterObjective(p){const d=CHAPTERS[p.region||0],s=chapterState(p);return {definition:d,state:s,title:d.title,text:s.stage===0?'Investigue '+d.landmark+' junto ao portal.':s.stage===1?'Recupere '+d.collectible+' dos inimigos da região.':s.stage===2?'Conclua uma masmorra desta região e estabilize o selo.':s.stage===3?'Retorne à Ilyra no ponto seguro para receber sua recompensa.':'Selo estabilizado. Prepare seu equipamento e siga para a próxima região.',progress:s.stage===1?(s.kills||0)+' / '+d.target+' fragmentos':s.stage===4?'CAPÍTULO CONCLUÍDO':'ETAPA '+(s.stage+1)+' / 4',goal:s.stage===0?d.point:s.stage===1?{x:21,y:23}:s.stage===2?{x:27,y:10}:{x:12,y:13}};}
